using Nafadh_Backend.DTOs;
using Nafadh_Backend.Enums;
using Nafadh_Backend.Models;
using Nafadh_Backend.Repositories;

namespace Nafadh_Backend.Services
{
    public class EvaluationTemplateService : IEvaluationTemplateService
    {
        private readonly IEvaluationTemplateRepository _repository;

        public EvaluationTemplateService(IEvaluationTemplateRepository repository)
        {
            _repository = repository;
        }

        // ==========================================
        // Get All Templates
        public async Task<List<EvaluationTemplateOutputDTO>> GetTemplatesAsync(NFD_EvaluationType? type)
        {
            return await GetTemplatesAsync(type, null, null);
        }

        // NEW: filter by module/stage
        public async Task<List<EvaluationTemplateOutputDTO>> GetTemplatesAsync(NFD_EvaluationType? type, int? moduleId, int? stage)
        {
            var templates = await _repository.GetTemplatesAsync(type, moduleId, stage);

            var result = new List<EvaluationTemplateOutputDTO>();

            foreach (var template in templates)
            {
                result.Add(new EvaluationTemplateOutputDTO
                {
                    TemplateId = template.TemplateId,
                    Type = template.Type,
                    ModuleId = template.ModuleId,
                    Stage = template.Stage,
                    CreatedByUserId = template.CreatedByUserId
                });
            }

            return result;
        }

        // ==========================================
        // Get Template Details
        public async Task<EvaluationTemplateDetailsDTO?> GetTemplateByIdAsync(int templateId)
        {
            var template = await _repository.GetTemplateByIdAsync(templateId);

            if (template == null)
                return null;

            var details = new EvaluationTemplateDetailsDTO
            {
                TemplateId = template.TemplateId,
                Type = template.Type,
                ModuleId = template.ModuleId,
                Stage = template.Stage,
                CreatedByUserId = template.CreatedByUserId
            };

            foreach (var criterion in template.EvaluationCriteria)
            {
                details.Criteria.Add(new EvaluationCriterionOutputDTO
                {
                    CriteriaId = criterion.CriteriaId,
                    TemplateId = criterion.TemplateId,
                    Name = criterion.Name,
                    Weight = criterion.Weight,
                    MaxPoints = criterion.MaxPoints
                });
            }

            return details;
        }

        // ==========================================
        // Create Template
        public async Task CreateTemplateAsync(EvaluationTemplateInputDTO input)
        {
            var template = new NFD_EvaluationTemplate
            {
                Type = input.Type,
                ModuleId = input.ModuleId,
                Stage = input.Stage,
                CreatedByUserId = input.CreatedByUserId
            };

            await _repository.AddTemplateAsync(template);
        }

        // ==========================================
        // Update Template
        public async Task<bool> UpdateTemplateAsync(int templateId, EvaluationTemplateInputDTO input)
        {
            var template = await _repository.GetTemplateByIdAsync(templateId);

            if (template == null)
                return false;

            template.Type = input.Type;
            template.ModuleId = input.ModuleId;
            template.Stage = input.Stage;
            template.CreatedByUserId = input.CreatedByUserId;

            await _repository.UpdateTemplateAsync(template);

            return true;
        }

        // ==========================================
        // Delete Template
        public async Task<bool> DeleteTemplateAsync(int templateId)
        {
            var template = await _repository.GetTemplateByIdAsync(templateId);

            if (template == null)
                return false;

            await _repository.DeleteTemplateAsync(template);

            return true;
        }
    }
}